import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, length, smoothstep, float } from 'three/tsl';
import { gsap } from 'gsap';
import * as Primitives from '@/primitives';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new THREE.Group();
  root.name = 'quote-panel-journal';

  const disposables = [];
  const timelines = [];

  // ---------------------------------------------------------------
  // Card geometry: extruded rounded rect (bevel + PBR, never flat)
  // ---------------------------------------------------------------
  const cardW = 1.8;
  const cardH = 1.3;
  const cardR = 0.07;
  const cardDepth = 0.09;

  function roundedRectShape(w, h, r) {
    const shape = new THREE.Shape();
    const x = -w / 2;
    const y = -h / 2;
    shape.moveTo(x, y + r);
    shape.lineTo(x, y + h - r);
    shape.quadraticCurveTo(x, y + h, x + r, y + h);
    shape.lineTo(x + w - r, y + h);
    shape.quadraticCurveTo(x + w, y + h, x + w, y + h - r);
    shape.lineTo(x + w, y + r);
    shape.quadraticCurveTo(x + w, y, x + w - r, y);
    shape.lineTo(x + r, y);
    shape.quadraticCurveTo(x, y, x, y + r);
    return shape;
  }

  const cardShape = roundedRectShape(cardW, cardH, cardR);
  const cardGeo = new THREE.ExtrudeGeometry(cardShape, {
    depth: cardDepth,
    bevelEnabled: true,
    bevelThickness: 0.014,
    bevelSize: 0.014,
    bevelSegments: 3,
    curveSegments: 8,
  });
  cardGeo.center();
  disposables.push(cardGeo);

  const cardMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(colors.ink),
    roughness: 0.55,
    metalness: 0.32,
    clearcoat: 0.15,
    clearcoatRoughness: 0.4,
    emissive: new THREE.Color(colors.surface),
    emissiveIntensity: 0.15,
    side: THREE.FrontSide,
  });
  disposables.push(cardMat);

  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  cardMesh.rotation.set(0, 0, 0);
  root.add(cardMesh);

  // subtle backing texture from feature-card.png (editorial paper grain)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      cardMat.map = tex;
      cardMat.roughnessMap = null;
      cardMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---------------------------------------------------------------
  // Accent edge spine (left side) — the one accent, <=10% of frame
  // ---------------------------------------------------------------
  const spineGeo = new THREE.BoxGeometry(0.045, cardH * 0.92, cardDepth * 1.35);
  disposables.push(spineGeo);
  const spineMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(colors.accent),
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 1.1,
    roughness: 0.45,
    metalness: 0.4,
    clearcoat: 0.1,
  });
  disposables.push(spineMat);
  const spine = new THREE.Mesh(spineGeo, spineMat);
  spine.position.set(-cardW / 2 + 0.03, 0, cardDepth * 0.1);
  root.add(spine);

  // ---------------------------------------------------------------
  // Decorative quotation mark ornament (typographic accent, not copy)
  // ---------------------------------------------------------------
  const quoteMark = ctx.fontAtlas.createText('"', {
    fontSize: 96,
    color: colors.paper,
    align: 'left',
  });
  quoteMark.position.set(-cardW / 2 + 0.16, cardH / 2 - 0.22, cardDepth + 0.01);
  root.add(quoteMark);

  // ---------------------------------------------------------------
  // Render provided text content verbatim (bridging idiom)
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let cursorY = cardH / 2 - 0.5;
  for (const item of items) {
    const isAttribution = item.role === 'caption' || item.role === 'attribution';
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? (isAttribution ? 26 : 40),
      color: isAttribution ? colors.accent : colors.paper,
      align: 'left',
      maxWidthPx: 420,
    });
    txt.position.set(-cardW / 2 + 0.18, cursorY, cardDepth + 0.01);
    root.add(txt);
    cursorY -= isAttribution ? 0.22 : 0.3;
    disposables.push(txt);
  }

  // ---------------------------------------------------------------
  // Contact shadow (grounding) — procedural radial via TSL
  // ---------------------------------------------------------------
  const shadowGeo = new THREE.PlaneGeometry(cardW * 1.35, cardH * 1.35);
  disposables.push(shadowGeo);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const centered = uv().sub(vec2(0.5, 0.5));
  const dist = length(centered);
  shadowMat.opacityNode = smoothstep(float(0.5), float(0.05), dist).mul(0.5);
  shadowMat.colorNode = float(0.0);
  disposables.push(shadowMat);
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -cardH / 2 - 0.02, -cardDepth);
  root.add(shadowMesh);

  // ---------------------------------------------------------------
  // Node-local rim/accent light (scene provides ambient 0.6 + key 1.2)
  // ---------------------------------------------------------------
  const rim = new THREE.PointLight(new THREE.Color(colors.accent), 0.7, 3.5);
  rim.position.set(0.6, 0.3, 0.9);
  root.add(rim);

  // ---------------------------------------------------------------
  // Idle motion: one slow breathing transform
  // ---------------------------------------------------------------
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(cardMesh.scale, { x: 1.015, y: 1.015, z: 1.015, duration: 2.6, ease: 'sine.inOut' });
  timelines.push(idleTl);

  // ---------------------------------------------------------------
  // Hover (rise-in, subtle) + press-down interaction timelines
  // ---------------------------------------------------------------
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(root.position, { y: '+=0.15', duration: 0.5, ease: 'power3.out' }, 0);
  hoverTl.to(spineMat, { emissiveIntensity: 1.6, duration: 0.3, ease: 'power2.out' }, 0);
  timelines.push(hoverTl);

  const pressTl = gsap.timeline({ paused: true });
  pressTl.to(cardMesh.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
  timelines.push(pressTl);

  root.userData.handlers = {
    onPointerEnter: () => { hoverTl.play(); },
    onPointerOver: () => { hoverTl.play(); },
    onPointerLeave: () => { hoverTl.reverse(); },
    onPointerOut: () => { hoverTl.reverse(); },
    onPointerDown: () => { pressTl.play(0); },
    onPointerUp: () => { pressTl.reverse(); },
    onClick: () => {
      pressTl.play(0).then?.(() => {});
      ctx.emit('hub-journal.select', { id: 'quote-panel', parent: 'hub-journal' });
    },
  };

  // ---------------------------------------------------------------
  // Cinematic primitives from config
  // ---------------------------------------------------------------
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const applyFn = ctx.primitives[prim.name];
    if (typeof applyFn === 'function') {
      const handle = applyFn(root, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------
  // Cleanup
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const h of primitiveHandles) h?.cleanup?.();
    for (const d of disposables) d?.dispose?.();
    cardMat.map?.dispose?.();
    cardGeo.dispose();
    spineGeo.dispose();
    spineMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
  };

  return root;
}
